  logic        mdc_s, mdc_d, mdio_s;
  logic        frame_act;
  logic        prev_bit;             // mdio sampled at previous mdc rising edge
  logic [5:0]  cnt;
  logic [31:0] shift;
  logic        read_frame, read_match;
  logic [4:0]  regad_q;

