  // DATA[15] edge); master samples it at the cnt==14 rising edge.
  wire drive_low = read_match && (cnt >= 6'd14) && (cnt <= 6'd29)
                   && (rd_reg[5'd29 - cnt[4:0]] == 1'b0);
  assign mdio = drive_low ? 1'b0 : 1'bz;
  assign irq  = frame_act && (cnt == 6'd29);

