          regs[shift[21:17]] <= {shift[14:0], mdio_s};   // write
        end
      end else begin
        shift <= {shift[30:0], mdio_s};
        cnt   <= cnt + 1'b1;
        if (cnt == 6'd1) begin
          read_frame <= (mdio_s == 1'b0) && (shift[0] == 1'b1); // OP == 10
        end
        if (cnt == 6'd6) begin
          read_match <= read_frame && ({shift[3:0], mdio_s} == PHY_ADDR[4:0]);
        end
        if (cnt == 6'd11) begin
